// Pseudocode for federated training loop
function train_round(tenant_config, local_data_uri, model, aggregator_uri){
  const local_model = train(model, load(local_data_uri));
  const update = compute_update(local_model, model);
  send_update_to_server(aggregator_uri, update);
}
```

